const rp = (n) => "Rp " + Math.round(n || 0).toLocaleString("id-ID");

function buildReceiptText(tx) {
  const dt = fmtFullDateTime(tx.timestamp);
  const line = "--------------------------------";
  const rows = [];
  rows.push("      DONAT GENDUY");
  rows.push("     Kaya Rasa Kaya Tradisi");
  rows.push("");
  rows.push("      Struk Pembelian");
  if (tx.status === "cancelled") rows.push("   ** DIBATALKAN **");
  rows.push(line);
  rows.push(`${dt.hari}, ${dt.tanggal}`);
  rows.push(`Jam ${dt.jam} - No. ${tx.id.slice(0, 8).toUpperCase()}`);
  rows.push(line);
  tx.items.forEach((it) => {
    const label = `${it.name} ${it.type === "flavor" ? `(${it.size})` : `(${it.unitQty}pcs)`} x${it.qty}`;
    rows.push(label);
    rows.push(rp(it.price * it.qty));
    if (it.type === "package") rows.push(`  isi: ${it.breakdown.map((b) => `${b.name} ${b.qty}`).join(", ")}`);
  });
  rows.push(line);
  rows.push(`Subtotal: ${rp(tx.subtotal)}`);
  if (tx.discountAmount > 0) rows.push(`Diskon: -${rp(tx.discountAmount)}`);
  rows.push(`TOTAL: ${rp(tx.total)}`);
  rows.push(`${paymentMethodLabel(tx.paymentMethod)}: ${rp(tx.cashPaid)}`);
  rows.push(`Kembali: ${rp(tx.change)}`);
  rows.push(line);
  rows.push("Terima kasih sudah membeli donat kami :)");
  return rows.join("\n");
}

function buildReceiptRows(tx) {
  const dt = fmtFullDateTime(tx.timestamp);
  const rows = [];
  rows.push({ type: "sub", text: "Struk Pembelian" });
  if (tx.status === "cancelled") rows.push({ type: "badge", text: "** TRANSAKSI DIBATALKAN **" });
  rows.push({ type: "divider" });
  rows.push({ type: "text", text: `${dt.hari}, ${dt.tanggal}` });
  rows.push({ type: "text", text: `Jam ${dt.jam} - No. ${tx.id.slice(0, 8).toUpperCase()}` });
  rows.push({ type: "divider" });
  tx.items.forEach((it) => {
    const label = `${it.name} ${it.type === "flavor" ? `(${it.size})` : `(${it.unitQty}pcs)`} x${it.qty}`;
    rows.push({ type: "kv", label, value: rp(it.price * it.qty) });
    if (it.type === "package") rows.push({ type: "sub", text: `  isi: ${it.breakdown.map((b) => `${b.name} ${b.qty}`).join(", ")}` });
  });
  rows.push({ type: "divider" });
  rows.push({ type: "kv", label: "Subtotal", value: rp(tx.subtotal) });
  if (tx.discountAmount > 0) rows.push({ type: "kv", label: "Diskon", value: `-${rp(tx.discountAmount)}` });
  rows.push({ type: "kv", label: "TOTAL", value: rp(tx.total), bold: true });
  rows.push({ type: "kv", label: "Tunai", value: rp(tx.cashPaid) });
  rows.push({ type: "kv", label: "Kembali", value: rp(tx.change) });
  rows.push({ type: "divider" });
  rows.push({ type: "center", text: "Terima kasih sudah membeli" });
  rows.push({ type: "center", text: "donat kami :)" });
  return rows;
}

function loadImageEl(src) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

// printWidth: kalau diisi (384 utk 58mm / 576 utk 80mm), struk dirender
// LANGSUNG di resolusi asli kertas printer itu (bukan dirender gede lalu
// diperkecil paksa) - ini yang bikin hasil cetak lebih tebal & gede jelas,
// karena ga ada proses "susutin gambar" yang bikin tulisan jadi tipis/pecah.
async function renderReceiptCanvas(tx, printWidth) {
  const rows = buildReceiptRows(tx);
  const isPrintMode = !!printWidth;
  const width = isPrintMode ? printWidth : 420;
  const s = isPrintMode ? printWidth / 384 : 1; // skala ukuran font/spasi relatif ke lebar 58mm
  const padX = isPrintMode ? 16 * s : 20;
  const fontPx = isPrintMode ? Math.round(24 * s) : 17;
  const fontBoldPx = isPrintMode ? Math.round(27 * s) : 19;
  const font = `bold ${fontPx}px 'Courier New', monospace`;
  const fontBold = `bold ${fontBoldPx}px 'Courier New', monospace`;
  const lineH = isPrintMode
    ? { sub: 32 * s, badge: 36 * s, divider: 28 * s, text: 32 * s, kv: 36 * s, center: 32 * s }
    : { sub: 24, badge: 28, divider: 20, text: 24, kv: 26, center: 24 };
  const dividerCount = Math.max(10, Math.floor((width - padX * 2) / (fontPx * 0.62)));
  const availW = width - padX * 2;
  const gapKv = isPrintMode ? 12 * s : 8;

  // Pecah teks jadi beberapa baris kalau kepanjangan buat lebar kertas -
  // ini yang mencegah tulisan numpuk/nabrak kayak sebelumnya.
  function wrapWords(ctxRef, text, maxWidth) {
    const words = String(text).split(" ");
    const out = [];
    let cur = "";
    words.forEach((w) => {
      const test = cur ? cur + " " + w : w;
      if (ctxRef.measureText(test).width > maxWidth && cur) {
        out.push(cur);
        cur = w;
      } else {
        cur = test;
      }
    });
    if (cur) out.push(cur);
    return out.length ? out : [""];
  }

  let logoImg = null;
  let logoDrawH = 0;
  const logoDrawW = isPrintMode ? Math.round(150 * s) : 180;
  try {
    logoImg = await loadImageEl(LOGO_RECEIPT);
    logoDrawH = (logoImg.height / logoImg.width) * logoDrawW;
  } catch (e) { /* kalau logo gagal dimuat, lanjut tanpa logo */ }

  // Canvas sementara cuma buat ngukur teks (menentukan perlu wrap atau tidak)
  const mctx = document.createElement("canvas").getContext("2d");

  // Pass 1: siapkan konten tiap baris (termasuk hasil wrap) & hitung tinggi total
  const plan = rows.map((r) => {
    if (r.type === "kv") {
      mctx.font = r.bold ? fontBold : font;
      const labelLines = wrapWords(mctx, r.label, availW);
      const valueW = mctx.measureText(r.value).width;
      const lastLineW = mctx.measureText(labelLines[labelLines.length - 1]).width;
      const fitsSameLine = labelLines.length === 1 && (lastLineW + gapKv + valueW) <= availW;
      const lines = fitsSameLine ? 1 : labelLines.length + 1;
      return { ...r, labelLines, fitsSameLine, h: lines * lineH.kv };
    }
    if (r.type === "sub" || r.type === "text" || r.type === "center") {
      mctx.font = font;
      const wrapped = wrapWords(mctx, r.text, availW);
      return { ...r, wrapped, h: wrapped.length * lineH[r.type] };
    }
    if (r.type === "badge") {
      mctx.font = fontBold;
      const wrapped = wrapWords(mctx, r.text, availW);
      return { ...r, wrapped, h: wrapped.length * lineH.badge };
    }
    return { ...r, h: lineH[r.type] || 24 };
  });

  let height = 24 + (logoImg ? logoDrawH + 16 : 0);
  plan.forEach((r) => { height += r.h; });
  height += 20;

  const canvas = document.createElement("canvas");
  // Mode download: supersample 3x biar tajam pas dizoom/dilihat di HP.
  // Mode cetak printer: gambar dirender PAS di lebar asli printer (scale=1)
  // - sengaja TIDAK di-supersample lalu diperkecil lagi, karena proses
  // "perkecil paksa" itu justru yang bikin hasil cetak jadi tipis/kecil.
  const scale = isPrintMode ? 1 : 3;
  canvas.width = width * scale;
  canvas.height = height * scale;
  const ctx = canvas.getContext("2d");
  ctx.scale(scale, scale);
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = "#000000";

  let y = 18;
  if (logoImg) {
    ctx.drawImage(logoImg, (width - logoDrawW) / 2, y, logoDrawW, logoDrawH);
    y += logoDrawH + 22;
  } else {
    y += 10;
  }

  plan.forEach((r) => {
    if (r.type === "sub") {
      ctx.font = font;
      ctx.textAlign = "left";
      r.wrapped.forEach((line) => { ctx.fillText(line, padX, y); y += lineH.sub; });
    } else if (r.type === "badge") {
      ctx.font = fontBold;
      ctx.textAlign = "center";
      r.wrapped.forEach((line) => { ctx.fillText(line, width / 2, y); y += lineH.badge; });
    } else if (r.type === "center") {
      ctx.font = font;
      ctx.textAlign = "center";
      r.wrapped.forEach((line) => { ctx.fillText(line, width / 2, y); y += lineH.center; });
    } else if (r.type === "divider") {
      ctx.font = font;
      ctx.textAlign = "left";
      ctx.fillText("-".repeat(isPrintMode ? dividerCount : 34), padX, y);
      y += lineH.divider;
    } else if (r.type === "text") {
      ctx.font = font;
      ctx.textAlign = "left";
      r.wrapped.forEach((line) => { ctx.fillText(line, padX, y); y += lineH.text; });
    } else if (r.type === "kv") {
      ctx.font = r.bold ? fontBold : font;
      if (r.fitsSameLine) {
        ctx.textAlign = "left";
        ctx.fillText(r.labelLines[0], padX, y);
        ctx.textAlign = "right";
        ctx.fillText(r.value, width - padX, y);
        y += lineH.kv;
      } else {
        ctx.textAlign = "left";
        r.labelLines.forEach((line) => { ctx.fillText(line, padX, y); y += lineH.kv; });
        ctx.textAlign = "right";
        ctx.fillText(r.value, width - padX, y);
        y += lineH.kv;
      }
    }
  });

  return canvas;
}

/* ------------------------------------------------------------------ */
/* CETAK LANGSUNG KE PRINTER BLUETOOTH (ESC/POS) - TANPA APK TAMBAHAN   */
/* ------------------------------------------------------------------ */
/*
  Cara kerja singkat:
  1. Struk dirender jadi gambar hitam-putih (pakai renderReceiptCanvas yang
     sudah ada), lalu diubah jadi format "raster bitmap" yang dimengerti
     printer thermal kecil (perintah ESC/POS: GS v 0).
  2. Gambar itu dikirim langsung ke printer lewat Bluetooth Low Energy (BLE)
     pakai Web Bluetooth API bawaan browser Chrome - TIDAK butuh RawBT atau
     app tambahan apa pun.

  CATATAN PENTING (biar ga bingung kalau gagal):
  - Ini cuma jalan kalau printer-nya jenis Bluetooth Low Energy (BLE).
    Sebagian printer struk mini yang dijual di marketplace itu Bluetooth
    "Classic"/SPP, bukan BLE - itu TIDAK akan kedeteksi lewat cara ini
    (ini keterbatasan dari sistem Android/Chrome, bukan dari kode ini).
  - Fitur ini butuh browser/APK yang mendukung Web Bluetooth API. Kalau
    dibuka lewat Chrome asli (browser Chrome biasa, atau APK hasil
    PWABuilder/TWA) biasanya jalan. Kalau dibuka lewat APK webview
    generik (banyak tool "website to APK" itu webview polos), fitur
    Bluetooth ini bisa saja tidak muncul/tidak berfungsi - itu bukan
    berarti kode-nya salah, tapi wrapper APK-nya tidak menyediakan akses
    itu ke halaman web di dalamnya.
  - Kalau di HP ini fitur ini tidak jalan, tombol "Cetak Struk" biasa dan
    "Unduh Struk" / RawBT di bawahnya tetap bisa dipakai sebagai cadangan.
*/

const PRINTER_STORAGE_KEY = "kdg_bt_printer_settings_v1";

// Beberapa service/characteristic Bluetooth yang paling umum dipakai
// printer thermal mini (GOOJPRT, Zjiang, Xprinter, dll)
const BT_PRINTER_SERVICE_UUIDS = [
  "000018f0-0000-1000-8000-00805f9b34fb",
  "0000ff00-0000-1000-8000-00805f9b34fb",
  "0000ffe0-0000-1000-8000-00805f9b34fb",
  "49535343-fe7d-4ae5-8fa9-9fafd205e455",
  "e7810a71-73ae-499d-8c15-faa9aef0c3f2",
  "0000ae30-0000-1000-8000-00805f9b34fb",
];

function loadPrinterSettings() {
  try {
    const raw = localStorage.getItem(PRINTER_STORAGE_KEY);
    return raw ? JSON.parse(raw) : { paperWidth: 384, deviceName: null };
  } catch (e) { return { paperWidth: 384, deviceName: null }; }
}
function savePrinterSettings(s) {
  try { localStorage.setItem(PRINTER_STORAGE_KEY, JSON.stringify(s)); } catch (e) { /* abaikan */ }
}

// State koneksi disimpan di luar React (bertahan selama app dibuka, tapi
// reset kalau app ditutup total - device perlu dihubungkan ulang sekali
// tiap buka app, ini batasan wajar dari Web Bluetooth)
let _btDevice = null;
let _btCharacteristic = null;

function isBluetoothPrintSupported() {
  return typeof navigator !== "undefined" && !!navigator.bluetooth;
}

async function findWritableCharacteristic(server) {
  const services = await server.getPrimaryServices();
  for (const service of services) {
    const chars = await service.getCharacteristics();
    for (const ch of chars) {
      if (ch.properties && (ch.properties.write || ch.properties.writeWithoutResponse)) {
        return ch;
      }
    }
  }
  return null;
}

async function connectBluetoothPrinter() {
  if (!isBluetoothPrintSupported()) {
    throw new Error("NO_BLUETOOTH_API");
  }
  const device = await navigator.bluetooth.requestDevice({
    acceptAllDevices: true,
    optionalServices: BT_PRINTER_SERVICE_UUIDS,
  });
  const server = await device.gatt.connect();
  const characteristic = await findWritableCharacteristic(server);
  if (!characteristic) throw new Error("NO_WRITABLE_CHARACTERISTIC");
  _btDevice = device;
  _btCharacteristic = characteristic;
  device.addEventListener("gattserverdisconnected", () => {
    _btDevice = null;
    _btCharacteristic = null;
  });
  const settings = loadPrinterSettings();
  savePrinterSettings({ ...settings, deviceName: device.name || "Printer Bluetooth" });
  return device.name || "Printer Bluetooth";
}

async function ensureBluetoothPrinterConnected() {
  if (_btDevice && _btDevice.gatt && _btDevice.gatt.connected && _btCharacteristic) {
    return _btDevice.name || "Printer Bluetooth";
  }
  return connectBluetoothPrinter();
}

function disconnectBluetoothPrinter() {
  try { if (_btDevice && _btDevice.gatt && _btDevice.gatt.connected) _btDevice.gatt.disconnect(); } catch (e) { /* abaikan */ }
  _btDevice = null;
  _btCharacteristic = null;
}

// Ubah canvas (hitam-putih) jadi perintah ESC/POS raster image (GS v 0)
function canvasToEscPosRaster(canvas, targetWidthPx) {
  const srcW = canvas.width;
  const srcH = canvas.height;
  const scale = targetWidthPx / srcW;
  const dstW = targetWidthPx - (targetWidthPx % 8); // harus kelipatan 8
  const dstH = Math.round(srcH * scale);

  const off = document.createElement("canvas");
  off.width = dstW;
  off.height = dstH;
  const ctx = off.getContext("2d");
  ctx.fillStyle = "#fff";
  ctx.fillRect(0, 0, dstW, dstH);
  ctx.drawImage(canvas, 0, 0, dstW, dstH);
  const imgData = ctx.getImageData(0, 0, dstW, dstH).data;

  const bytesPerRow = dstW / 8;
  const bitmap = new Uint8Array(bytesPerRow * dstH);
  for (let y = 0; y < dstH; y++) {
    for (let x = 0; x < dstW; x++) {
      const idx = (y * dstW + x) * 4;
      const r = imgData[idx], g = imgData[idx + 1], b = imgData[idx + 2], a = imgData[idx + 3];
      const gray = (r * 0.3 + g * 0.59 + b * 0.11);
      const isBlack = a > 60 && gray < 170;
      if (isBlack) {
        const byteIndex = y * bytesPerRow + (x >> 3);
        bitmap[byteIndex] |= 0x80 >> (x % 8);
      }
    }
  }

  const xL = bytesPerRow & 0xff;
  const xH = (bytesPerRow >> 8) & 0xff;
  const yL = dstH & 0xff;
  const yH = (dstH >> 8) & 0xff;

  const header = new Uint8Array([0x1d, 0x76, 0x30, 0x00, xL, xH, yL, yH]);
  const out = new Uint8Array(header.length + bitmap.length);
  out.set(header, 0);
  out.set(bitmap, header.length);
  return out;
}

function concatBytes(chunks) {
  const total = chunks.reduce((s, c) => s + c.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  chunks.forEach((c) => { out.set(c, offset); offset += c.length; });
  return out;
}

async function sendBytesToPrinter(characteristic, bytes) {
  const CHUNK_SIZE = 180; // aman untuk kebanyakan modul BLE printer
  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
    const chunk = bytes.slice(i, i + CHUNK_SIZE);
    if (characteristic.properties.writeWithoutResponse) {
      await characteristic.writeValueWithoutResponse(chunk);
    } else {
      await characteristic.writeValue(chunk);
    }
    await new Promise((res) => setTimeout(res, 20));
  }
}

async function printReceiptToBluetooth(tx, opts) {
  const paperWidth = (opts && opts.paperWidth) || 384; // 384px ~ 58mm, 576px ~ 80mm
  const name = await ensureBluetoothPrinterConnected();
  const canvas = await renderReceiptCanvas(tx, paperWidth);
  const raster = canvasToEscPosRaster(canvas, paperWidth);
  const init = new Uint8Array([0x1b, 0x40]); // ESC @ (reset printer)
  const feedAndCut = new Uint8Array([0x0a, 0x0a, 0x0a, 0x0a]); // feed 4 baris (banyak printer mini ga punya pisau otomatis)
  const payload = concatBytes([init, raster, feedAndCut]);
  await sendBytesToPrinter(_btCharacteristic, payload);
  return name;
}

