/* Laporan (harian/bulanan) sebagai dokumen .doc - bisa dibuka WPS/Word */
/* ------------------------------------------------------------------ */
function computeReportData(tx, onlineOrders, stockLog, master, matchFn, productions) {
  const scoped = tx.filter((t) => t.status === "completed" && matchFn(t.timestamp));
  const cancelled = tx.filter((t) => t.status === "cancelled" && matchFn(t.timestamp));
  const onlineScoped = (onlineOrders || []).filter((o) => o.status === "completed" && matchFn(o.timestamp));
  const onlineCancelled = (onlineOrders || []).filter((o) => o.status === "cancelled" && matchFn(o.timestamp));
  const stockScoped = (stockLog || []).filter((l) => matchFn(l.timestamp));

  const offlineRevenue = scoped.reduce((s, t) => s + t.total, 0);
  const onlineGrossRevenue = onlineScoped.reduce((s, o) => s + o.gross, 0);
  const onlineNetRevenue = onlineScoped.reduce((s, o) => s + o.net, 0);
  const revenue = offlineRevenue + onlineGrossRevenue;

  const itemQty = (items) => items.reduce((a, i) => a + (i.type === "flavor" ? i.qty : i.unitQty * i.qty), 0);
  const itemsSold = scoped.reduce((s, t) => s + itemQty(t.items), 0) + onlineScoped.reduce((s, o) => s + itemQty(o.items), 0);

  const flavorMap = {};
  master.flavors.forEach((f) => (flavorMap[f.name] = 0));
  const tallyFlavors = (items) => items.forEach((it) => {
    if (it.type === "flavor") flavorMap[it.name] = (flavorMap[it.name] || 0) + it.qty;
    else if (it.type === "package") (it.breakdown || []).forEach((b) => { flavorMap[b.name] = (flavorMap[b.name] || 0) + b.qty * it.qty; });
  });
  scoped.forEach((t) => tallyFlavors(t.items));
  onlineScoped.forEach((o) => tallyFlavors(o.items));
  const flavorArr = Object.entries(flavorMap).map(([name, qty]) => ({ name, qty }));
  const best = [...flavorArr].sort((a, b) => b.qty - a.qty).slice(0, 5);

  // pendapatan per channel: tunai/qris/transfer (offline) + gofood/grabfood/shopeefood (online)
  const channelRevenue = { tunai: 0, qris: 0, transfer: 0, gofood: 0, grabfood: 0, shopeefood: 0 };
  scoped.forEach((t) => { const pm = t.paymentMethod || "tunai"; channelRevenue[pm] = (channelRevenue[pm] || 0) + t.total; });
  onlineScoped.forEach((o) => { if (channelRevenue[o.platform] !== undefined) channelRevenue[o.platform] += o.gross; });

  // pemakaian & penambahan bahan baku / stok donat (net dari pembatalan)
  const isRestore = (r) => (r || "").startsWith("Pembatalan");
  const ingredientUsageMap = {};
  const ingredientRestockMap = {};
  const donatRestock = { Mini: { count: 0, qty: 0 }, Maxi: { count: 0, qty: 0 } };
  stockScoped.forEach((l) => {
    if (l.category === "ingredient" && l.type === "keluar") {
      ingredientUsageMap[l.itemName] = ingredientUsageMap[l.itemName] || { qty: 0, unit: l.unit };
      ingredientUsageMap[l.itemName].qty += l.qty;
    }
    if (l.category === "ingredient" && l.type === "masuk" && isRestore(l.reason)) {
      ingredientUsageMap[l.itemName] = ingredientUsageMap[l.itemName] || { qty: 0, unit: l.unit };
      ingredientUsageMap[l.itemName].qty -= l.qty;
    }
    if (l.category === "ingredient" && l.type === "masuk" && !isRestore(l.reason)) {
      ingredientRestockMap[l.itemName] = ingredientRestockMap[l.itemName] || { qty: 0, unit: l.unit, count: 0 };
      ingredientRestockMap[l.itemName].qty += l.qty;
      ingredientRestockMap[l.itemName].count += 1;
    }
    if (l.category === "donat" && l.type === "masuk" && !isRestore(l.reason) && donatRestock[l.itemId]) {
      donatRestock[l.itemId].count += 1;
      donatRestock[l.itemId].qty += l.qty;
    }
  });
  const ingredientUsageList = Object.entries(ingredientUsageMap).filter(([, v]) => v.qty > 0).sort((a, b) => b[1].qty - a[1].qty);
  const ingredientRestockList = Object.entries(ingredientRestockMap).sort((a, b) => b[1].qty - a[1].qty);
  const donatRestockTotalCount = donatRestock.Mini.count + donatRestock.Maxi.count;
  const donatRestockTotalQty = donatRestock.Mini.qty + donatRestock.Maxi.qty;
  const ingredientRestockTotalCount = ingredientRestockList.reduce((s, [, v]) => s + v.count, 0);

  // riwayat produksi pada periode ini
  const productionsScoped = (productions || []).filter((p) => matchFn(p.timestamp)).sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));
  const productionCount = productionsScoped.length;
  const productionOutputMaxi = productionsScoped.reduce((s, p) => s + p.outputMaxi, 0);
  const productionOutputMini = productionsScoped.reduce((s, p) => s + p.outputMini, 0);
  const productionDays = [...new Set(productionsScoped.map((p) => dateStr(new Date(p.timestamp))))];
  const productionTotalBiaya = productionsScoped.reduce((s, p) => s + (p.totalBiaya || 0), 0);
  const productionAvgHpp = (productionOutputMaxi + productionOutputMini) > 0 ? productionTotalBiaya / (productionOutputMaxi + productionOutputMini) : 0;

  // detail transaksi gabungan (offline + online), diurutkan dari terbaru
  const itemsText = (items) => items.map((it) => (it.name + " " + (it.type === "flavor" ? ("(" + it.size + ")") : ("(" + it.unitQty + "pcs)")) + " x" + it.qty)).join("; ");
  const detailRows = [
    ...scoped.map((t) => ({ timestamp: t.timestamp, itemsText: itemsText(t.items), total: t.total, channel: paymentMethodLabel(t.paymentMethod) + " (Offline)" })),
    ...onlineScoped.map((o) => ({ timestamp: o.timestamp, itemsText: itemsText(o.items), total: o.gross, channel: o.platformName || o.platform })),
  ].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  return {
    orderCount: scoped.length + onlineScoped.length,
    cancelledCount: cancelled.length + onlineCancelled.length,
    revenue, offlineRevenue, onlineGrossRevenue, onlineNetRevenue, channelRevenue,
    itemsSold, best, detailRows,
    ingredientUsageList, ingredientRestockList, ingredientRestockTotalCount,
    donatRestock, donatRestockTotalCount, donatRestockTotalQty,
    productionsScoped, productionCount, productionOutputMaxi, productionOutputMini, productionDays,
    productionTotalBiaya, productionAvgHpp,
  };
}

