async function shareOrDownloadDoc(html, filename, showToast) {
  const blob = new Blob(["\ufeff", html], { type: "application/msword" });
  try {
    const file = new File([blob], filename, { type: "application/msword" });
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      await navigator.share({ files: [file], title: filename });
      return;
    }
  } catch (e) {
    if (e && e.name === "AbortError") return;
  }
  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 30000);
    if (showToast) showToast("Laporan berhasil diunduh, bisa dibuka pakai WPS Office / Word", "success");
  } catch (e) {
    if (showToast) showToast("Gagal membuat file laporan", "error");
  }
}

