const STORAGE_PREFIX = "kasir-donat-genduy:";
const storage = {
  async get(key) {
    const raw = window.localStorage.getItem(STORAGE_PREFIX + key);
    if (raw === null) throw new Error("key not found: " + key);
    return { key, value: raw };
  },
  async set(key, value) {
    window.localStorage.setItem(STORAGE_PREFIX + key, value);
    return { key, value };
  },
  async delete(key) {
    window.localStorage.removeItem(STORAGE_PREFIX + key);
    return { key, deleted: true };
  },
};

const uid = () => (crypto.randomUUID ? crypto.randomUUID() : "id-" + Date.now() + "-" + Math.random().toString(16).slice(2));


function sameDay(iso, ref) {
  const d = new Date(iso), r = ref;
  return d.getFullYear() === r.getFullYear() && d.getMonth() === r.getMonth() && d.getDate() === r.getDate();
}
function sameMonth(iso, ref) {
  const d = new Date(iso), r = ref;
  return d.getFullYear() === r.getFullYear() && d.getMonth() === r.getMonth();
}
function dateStr(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function sameAsDateStr(iso, ymd) {
  return dateStr(new Date(iso)) === ymd;
}
function fmtDateTime(iso) {
  return new Date(iso).toLocaleString("id-ID", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
}
function fmtFullDateTime(iso) {
  const d = new Date(iso);
  const hari = d.toLocaleDateString("id-ID", { weekday: "long" });
  const tanggal = d.toLocaleDateString("id-ID", { day: "2-digit", month: "long", year: "numeric" });
  const jam = d.toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit" });
  return { hari, tanggal, jam, full: `${hari}, ${tanggal} · ${jam}` };
}
function fmtDateLabel(ymd) {
  const [y, m, d] = ymd.split("-").map(Number);
  return new Date(y, m - 1, d).toLocaleDateString("id-ID", { weekday: "long", day: "2-digit", month: "long", year: "numeric" });
}
function fmtMonthLabel(d) {
  return d.toLocaleDateString("id-ID", { month: "long", year: "numeric" });
}
function nowHM(d) {
  return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}
function isShopOpen(hm, open, close) {
  if (!open || !close) return true;
  if (open === close) return true;
  if (open < close) return hm >= open && hm < close;
  return hm >= open || hm < close; // jam operasional lewat tengah malam
}

// Label metode pembayaran offline (dipakai di riwayat, struk, & laporan)
function paymentMethodLabel(pm) {
  if (pm === "qris") return "QRIS";
  if (pm === "transfer") return "Transfer";
  return "Tunai";
}

