// Harga online bisa beda dari harga offline (biasanya lebih tinggi buat
// nutup komisi platform). Kalau field harga online belum diisi (data
// lama sebelum fitur ini ada), otomatis jatuh balik ke harga offline.
function getFlavorOnlinePrice(flavor, size) {
  const v = size === "Maxi" ? flavor.priceMaxiOnline : flavor.priceMiniOnline;
  return v === undefined || v === null || v === "" ? (size === "Maxi" ? flavor.priceMaxi : flavor.priceMini) : v;
}
function getPackageOnlinePrice(pkg) {
  const v = pkg.priceOnline;
  return v === undefined || v === null || v === "" ? pkg.price : v;
}
function getIngredientPricePerUnit(ing) {
  if (!ing || !ing.bulkQty || Number(ing.bulkQty) <= 0) return 0;
  return Number(ing.bulkPrice || 0) / Number(ing.bulkQty);
}
// Hitung biaya sebuah Produk Olahan (Butter Cream, Krim Coklat, dll) dari
// bahan-bahan mentahnya. Hasilnya dipakai buat "mengisi" harga per gram di
// master.ingredients (lihat upsertSubRecipeIngredient), jadi Produk Olahan
// bisa dipilih di resep rasa persis kayak bahan baku biasa.
function computeSubRecipeCost(subRecipe, ingredients) {
  let totalWeight = 0, totalCost = 0;
  (subRecipe.ingredients || []).forEach((r) => {
    const ing = ingredients.find((i) => i.id === r.ingredientId);
    const qty = Number(r.qty) || 0;
    totalWeight += qty;
    if (ing) totalCost += getIngredientPricePerUnit(ing) * qty;
  });
  const pricePerGram = totalWeight > 0 ? totalCost / totalWeight : 0;
  return { totalWeight, totalCost, pricePerGram };
}
// Simpan/perbarui Produk Olahan sebagai entri di master.ingredients juga,
// biar bisa langsung dipilih di resep rasa & ikut kepotong stoknya kayak
// bahan baku biasa. Stok tidak diubah di sini (biar aman), cuma harganya.
function upsertSubRecipeIngredient(ingredients, subRecipe) {
  const { totalWeight, totalCost } = computeSubRecipeCost(subRecipe, ingredients);
  const idx = ingredients.findIndex((i) => i.id === subRecipe.ingredientId);
  const base = idx >= 0 ? ingredients[idx] : { id: subRecipe.ingredientId, stock: 0, unit: "gram" };
  const updated = { ...base, name: subRecipe.name, unit: "gram", bulkPrice: totalCost, bulkQty: totalWeight, isSubRecipe: true, subRecipeId: subRecipe.id };
  if (idx >= 0) {
    const copy = ingredients.slice();
    copy[idx] = updated;
    return copy;
  }
  return [...ingredients, updated];
}

