/* ------------------------------------------------------------------ */
/* BACKUP MANUAL: export semua data jadi file .json, & import buat     */
/* pulihkan dari file itu. Filenya bisa disimpan/dipindah ke folder    */
/* mana pun lewat menu "Simpan ke Files" / "Save to" pas share.        */
/* ------------------------------------------------------------------ */
function BackupSection({ master, tx, stockLog, opsState, onlineOrders, expenses, capital, productions, setMaster, setTx, setStockLog, setOpsState, setOnlineOrders, setExpenses, setCapital, setProductions, showToast }) {
  const [importing, setImporting] = useState(false);
  const [pendingImport, setPendingImport] = useState(null);
  const fileInputRef = useRef(null);

  async function handleExport() {
    const payload = {
      app: "Donat Genduy", backupVersion: 1, exportedAt: new Date().toISOString(),
      master, tx, stockLog, opsState, onlineOrders, expenses, capital, productions,
    };
    const json = JSON.stringify(payload, null, 2);
    const filename = `Backup-DonatGenduy-${dateStr(new Date())}.json`;
    const blob = new Blob([json], { type: "application/json" });
    try {
      const file = new File([blob], filename, { type: "application/json" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({ files: [file], title: filename });
        showToast("Backup siap disimpan — pilih folder tujuan di menu share", "success");
        return;
      }
    } catch (e) {
      if (e && e.name === "AbortError") return;
    }
    try {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 30000);
      showToast("Backup berhasil diunduh ke folder Download", "success");
    } catch (e) {
      showToast("Gagal membuat file backup", "error");
    }
  }

  function handleFilePicked(e) {
    const file = e.target.files && e.target.files[0];
    e.target.value = ""; // biar bisa pilih file yang sama lagi kalau perlu
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      try {
        const data = JSON.parse(reader.result);
        if (!data || typeof data !== "object" || !data.master) {
          showToast("File ini bukan file backup Donat Genduy yang valid", "error");
          return;
        }
        setPendingImport(data);
      } catch (e) {
        showToast("File backup rusak / tidak bisa dibaca", "error");
      }
    };
    reader.readAsText(file);
  }

  function confirmImport() {
    const data = pendingImport;
    if (!data) return;
    if (data.master) setMaster(data.master);
    if (data.tx) setTx(data.tx);
    if (data.stockLog) setStockLog(data.stockLog);
    if (data.opsState) setOpsState(data.opsState);
    if (data.onlineOrders) setOnlineOrders(data.onlineOrders);
    if (data.expenses) setExpenses(data.expenses);
    if (data.capital) setCapital(data.capital);
    if (data.productions) setProductions(data.productions);
    setPendingImport(null);
    showToast("Data berhasil dipulihkan dari backup", "success");
  }

  return (
    <div>
      <p className="font-display font-bold text-sm mb-1.5" style={{ color: C.choco }}>Backup Manual</p>
      <p className="text-xs mb-4" style={{ color: C.inkSoft }}>
        Simpan salinan semua data (stok, transaksi, pesanan online, pengeluaran, modal) jadi satu file yang bisa kamu taruh di folder mana aja di HP — misalnya Google Drive, folder Download, atau kartu SD.
      </p>

      <Btn variant="primary" className="w-full mb-2.5" onClick={handleExport}>
        <Download size={16} /> Export / Download Backup
      </Btn>
      <p className="text-[11px] mb-5" style={{ color: C.inkSoft }}>
        Kalau muncul menu share, pilih "Simpan ke Files" / "Save to Drive" biar bisa milih folder sendiri. Kalau tidak, file otomatis masuk ke folder Download HP.
      </p>

      <div className="h-px mb-5" style={{ background: C.line }} />

      <p className="font-display font-bold text-sm mb-1.5" style={{ color: C.choco }}>Pulihkan dari Backup</p>
      <p className="text-xs mb-3" style={{ color: C.inkSoft }}>
        Pilih file backup (.json) yang pernah kamu export. <b>Ini akan menimpa semua data yang ada sekarang</b> — pastikan sudah benar sebelum lanjut.
      </p>
      <input ref={fileInputRef} type="file" accept="application/json,.json" onChange={handleFilePicked} className="hidden" />
      <Btn variant="outline" className="w-full" onClick={() => fileInputRef.current && fileInputRef.current.click()}>
        <RefreshCw size={16} /> Pilih File Backup
      </Btn>

      {pendingImport && (
        <Modal title="Pulihkan Data dari Backup?" onClose={() => setPendingImport(null)}>
          <p className="text-sm mb-2" style={{ color: C.ink }}>
            File ini dibuat pada <b>{pendingImport.exportedAt ? fmtDateTime(pendingImport.exportedAt) : "waktu tidak diketahui"}</b>.
          </p>
          <p className="text-sm mb-4" style={{ color: C.warn }}>
            Semua data yang ada di app sekarang (stok, transaksi, pesanan online, pengeluaran, modal) akan <b>diganti total</b> dengan isi file ini dan tidak bisa dibatalkan.
          </p>
          <div className="flex gap-2">
            <Btn variant="outline" className="flex-1" onClick={() => setPendingImport(null)}>Batal</Btn>
            <Btn variant="danger" className="flex-1" onClick={confirmImport}>Ya, Pulihkan</Btn>
          </div>
        </Modal>
      )}
    </div>
  );
}

function SyncSection({ cloudStatus, cloudError, authUser, authBusy, signInGoogle, signOutGoogle, showToast }) {
  const [debugMsg, setDebugMsg] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const r = await storage.get("kdg_last_login_debug");
        if (r && r.value) setDebugMsg(r.value);
      } catch (e) { /* belum ada percobaan login sebelumnya */ }
    })();
  }, [authUser, cloudStatus]);

  return (
    <div>
      <p className="text-xs mb-4" style={{ color: C.inkSoft }}>
        Sambungkan ke akun Google supaya data (stok, transaksi, laporan) otomatis sinkron di semua HP/PC yang login pakai akun Google yang sama. Tinggal masuk pakai Google — ga perlu setting apa-apa lagi.
      </p>

      {(cloudStatus === "off" || cloudStatus === "connecting") && (
        <div className="rounded-xl px-3 py-2.5 mb-4 flex items-center gap-2" style={{ background: C.amberBg, color: C.amber }}>
          <Loader2 size={14} className="animate-spin" /> <span className="text-xs font-semibold">Menyambungkan ke cloud…</span>
        </div>
      )}

      {cloudStatus === "error" && (
        <div className="rounded-xl px-3 py-2.5 mb-4 text-xs" style={{ background: C.warnBg, color: C.warn }}>
          Gagal menyambung ke cloud: {cloudError}. Coba tutup dan buka lagi app-nya, atau cek koneksi internet.
        </div>
      )}

      {debugMsg && !authUser && (
        <div className="rounded-xl px-3 py-2.5 mb-4 text-[11px]" style={{ background: C.surfaceAlt, color: C.inkSoft }}>
          Info percobaan login terakhir: {debugMsg}
          <br />(kalau login tetap gagal terus, screenshot baris ini dan kirim ke Claude biar dicek)
        </div>
      )}

      {(cloudStatus === "ready" || cloudStatus === "on") && !authUser && (
        <div className="rounded-2xl p-3.5 mb-4" style={{ background: C.surface, border: `1.5px solid ${C.line}` }}>
          <p className="font-semibold text-sm mb-2" style={{ color: C.choco }}>Masuk dengan Google</p>
          <p className="text-xs mb-3" style={{ color: C.inkSoft }}>Setelah login, data otomatis kesimpen ke akun Google ini. Login pakai akun yang sama di HP/PC lain buat lihat data yang sama persis - ga perlu setting ulang.</p>
          <Btn variant="primary" className="w-full" disabled={authBusy} onClick={signInGoogle}>
            {authBusy ? <Loader2 size={15} className="animate-spin" /> : <Cloud size={15} />} Masuk dengan Google
          </Btn>
        </div>
      )}

      {cloudStatus === "on" && authUser && (
        <div className="rounded-2xl p-3.5 mb-4" style={{ background: C.mintBg }}>
          <div className="flex items-center gap-2.5 mb-3">
            {authUser.photo ? (
              <img src={authUser.photo} alt="" className="w-9 h-9 rounded-full" />
            ) : (
              <div className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: C.mint }}><Cloud size={16} color="#fff" /></div>
            )}
            <div>
              <p className="font-semibold text-sm" style={{ color: C.choco }}>{authUser.name || authUser.email}</p>
              <p className="text-[11px] flex items-center gap-1" style={{ color: C.mint }}><Cloud size={11} /> Tersinkron otomatis</p>
            </div>
          </div>
          <Btn variant="outline" className="w-full" onClick={signOutGoogle}>Logout dari akun ini</Btn>
        </div>
      )}
    </div>
  );
}

function ResetDataSection({ master, setMaster, setTx, setStockLog, setOpsState, setOnlineOrders, setExpenses, setProductions, showToast }) {
  const [opts, setOpts] = useState({ tx: true, stockLog: true, online: true, expenses: true, productions: true, sizeStock: false, ingredientStock: false });
  const [confirmMode, setConfirmMode] = useState(null); // 'partial' | 'total'
  const [confirmText, setConfirmText] = useState("");

  function toggle(key) { setOpts((o) => ({ ...o, [key]: !o[key] })); }

  function runPartialReset() {
    if (opts.tx) setTx([]);
    if (opts.stockLog) setStockLog([]);
    if (opts.online) setOnlineOrders([]);
    if (opts.expenses) setExpenses([]);
    if (opts.productions) setProductions([]);
    if (opts.tx || opts.stockLog) setOpsState({ lastRecapDate: null });
    if (opts.sizeStock || opts.ingredientStock) {
      setMaster((m) => ({
        ...m,
        sizes: opts.sizeStock ? { Maxi: { stock: 0 }, Mini: { stock: 0 } } : m.sizes,
        ingredients: opts.ingredientStock ? m.ingredients.map((i) => ({ ...i, stock: 0 })) : m.ingredients,
      }));
    }
    showToast("Data yang dipilih berhasil direset", "success");
    setConfirmMode(null);
    setConfirmText("");
  }

  function runTotalReset() {
    setMaster(JSON.parse(JSON.stringify(DEFAULT_MASTER)));
    setTx([]);
    setStockLog([]);
    setOnlineOrders([]);
    setExpenses([]);
    setProductions([]);
    setOpsState({ lastRecapDate: null });
    showToast("Semua data dikembalikan ke pengaturan awal", "success");
    setConfirmMode(null);
    setConfirmText("");
  }

  return (
    <div>
      <p className="text-xs mb-4" style={{ color: C.inkSoft }}>
        Pakai ini buat bersihin data percobaan sebelum aplikasi mulai dipakai jualan beneran. Tindakan di sini tidak bisa dibatalkan, jadi pastikan dulu sebelum lanjut.
      </p>

      <div className="rounded-2xl p-3.5 mb-4" style={{ background: C.surface, border: `1.5px solid ${C.line}` }}>
        <p className="font-semibold text-sm mb-1" style={{ color: C.choco }}>Reset Sebagian</p>
        <p className="text-[11px] mb-3" style={{ color: C.inkSoft }}>Pilih data apa saja yang mau dihapus. Menu, harga, resep, dan jam operasional tidak akan ikut terhapus.</p>
        <div className="space-y-2 mb-3">
          {[
            ["tx", "Riwayat Transaksi & Laporan Penjualan"],
            ["stockLog", "Riwayat Keluar-Masuk Bahan Baku"],
            ["online", "Riwayat Pesanan Online"],
            ["expenses", "Riwayat Pengeluaran Harian"],
            ["productions", "Riwayat Produksi"],
            ["sizeStock", "Stok Donat Plain Maxi & Mini (jadi 0)"],
            ["ingredientStock", "Stok Semua Bahan Baku (jadi 0)"],
          ].map(([key, label]) => (
            <label key={key} className="flex items-center gap-2.5 rounded-xl p-2.5" style={{ background: C.surfaceAlt }}>
              <input type="checkbox" checked={opts[key]} onChange={() => toggle(key)} className="w-4 h-4" style={{ accentColor: C.glaze }} />
              <span className="text-xs font-semibold" style={{ color: C.ink }}>{label}</span>
            </label>
          ))}
        </div>
        <Btn variant="danger" className="w-full" disabled={!opts.tx && !opts.stockLog && !opts.online && !opts.expenses && !opts.productions && !opts.sizeStock && !opts.ingredientStock} onClick={() => setConfirmMode("partial")}>
          <RotateCcw size={15} /> Reset Data Terpilih
        </Btn>
      </div>

      <div className="rounded-2xl p-3.5" style={{ background: C.warnBg }}>
        <p className="font-semibold text-sm mb-1" style={{ color: C.warn }}>Reset Total (Kembali ke Awal)</p>
        <p className="text-[11px] mb-3" style={{ color: C.warn }}>Menghapus SEMUA data: transaksi, riwayat bahan baku, stok, varian rasa, paket, bahan baku, dan jam operasional — aplikasi kembali seperti baru pertama kali dipakai.</p>
        <Btn variant="danger" className="w-full" onClick={() => setConfirmMode("total")}>
          <Trash2 size={15} /> Reset Total Semua Data
        </Btn>
      </div>

      {confirmMode && (
        <Modal title="Konfirmasi Reset" onClose={() => { setConfirmMode(null); setConfirmText(""); }}>
          <div className="rounded-xl px-3 py-2.5 mb-4 flex items-center gap-2" style={{ background: C.warnBg }}>
            <AlertTriangle size={16} color={C.warn} />
            <p className="text-xs font-semibold" style={{ color: C.warn }}>Tindakan ini tidak bisa dibatalkan.</p>
          </div>
          <p className="text-sm mb-3" style={{ color: C.ink }}>
            {confirmMode === "total"
              ? "Semua data termasuk menu, rasa, paket, dan bahan baku akan dihapus dan kembali ke pengaturan awal."
              : "Data yang lo centang di atas akan dihapus permanen."}
          </p>
          <Field label='Ketik "RESET" untuk konfirmasi'>
            <TextInput value={confirmText} onChange={(e) => setConfirmText(e.target.value)} placeholder="RESET" />
          </Field>
          <Btn
            variant="danger" className="w-full"
            disabled={confirmText.trim().toUpperCase() !== "RESET"}
            onClick={confirmMode === "total" ? runTotalReset : runPartialReset}
          >
            Ya, Reset Sekarang
          </Btn>
        </Modal>
      )}
    </div>
  );
}

