function PackageForm({ pkg, ingredients, onClose, onSave }) {
  const [name, setName] = useState(pkg?.name || "");
  const [size, setSize] = useState(pkg?.size || "Maxi");
  const [qty, setQty] = useState(pkg?.qty ?? "");
  const [price, setPrice] = useState(pkg?.price ?? "");
  const [priceOnline, setPriceOnline] = useState(pkg?.priceOnline ?? "");
  const [rows, setRows] = useState(pkg?.recipe?.length ? pkg.recipe.map((r) => ({ ...r })) : []);

  function submit() {
    if (!name.trim() || !qty || !price) return;
    onSave({ name: name.trim(), size, qty: Number(qty), price: Number(price), priceOnline: priceOnline === "" ? null : Number(priceOnline), recipe: rows.filter((r) => r.qty > 0) });
  }

  return (
    <Modal title={pkg ? "Ubah Paket" : "Tambah Paket"} onClose={onClose} wide>
      <Field label="Nama Paket"><TextInput value={name} onChange={(e) => setName(e.target.value)} placeholder="Contoh: 1 Lusin" /></Field>
      <Field label="Ukuran Donat">
        <Select value={size} onChange={(e) => setSize(e.target.value)}>
          <option value="Maxi">Maxi</option>
          <option value="Mini">Mini</option>
        </Select>
      </Field>
      <Field label="Jumlah Isi (pcs)"><TextInput type="number" value={qty} onChange={(e) => setQty(e.target.value)} placeholder="12" /></Field>
      <div className="grid grid-cols-2 gap-3">
        <Field label="Harga Offline (Kasir)"><TextInput type="number" value={price} onChange={(e) => setPrice(e.target.value)} placeholder="80000" /></Field>
        <Field label="Harga Online (GoFood/dll)"><TextInput type="number" value={priceOnline} onChange={(e) => setPriceOnline(e.target.value)} placeholder={price ? `Default: ${price}` : "90000"} /></Field>
      </div>
      <p className="text-[11px] mb-3 -mt-2.5" style={{ color: C.inkSoft }}>Kosongkan Harga Online kalau mau sama persis dengan Harga Offline.</p>

      {ingredients.length === 0 && <p className="text-xs mb-3" style={{ color: C.inkSoft }}>Belum ada bahan baku, tambahkan dulu di tab Bahan.</p>}
      <div className="rounded-2xl p-3 mb-1" style={{ background: C.surfaceAlt }}>
        <RecipeRows label="Bahan Pendukung Paket (contoh: box, mika)" rows={rows} setRows={setRows} ingredients={ingredients} />
      </div>
      <p className="text-[11px] mb-4" style={{ color: C.inkSoft }}>Bahan ini otomatis kepotong tiap paket ini terjual, di luar bahan rasa donat yang dipilih di dalamnya.</p>

      <Btn variant="primary" className="w-full mt-1" onClick={submit}>Simpan</Btn>
    </Modal>
  );
}

